+static size_t GetUserWorkspaceSize(gert::TilingContext *context, MatmulAllreduceAddRmsnorm910cTilingData *tiling)
+{
+    static constexpr size_t fineGrainReadyWorkspaceBytes = 28 * 64;
+    MatMulInfo mmInfo;
+    GetMmInfo(context, tiling, &mmInfo);
+    QuantInfo quantInfo = tiling->matmulAllreduceAddRmsnormInfo.quantInfo;
+    return fineGrainReadyWorkspaceBytes + GetWorkspaceDetail(FP16FP16_FP32_FP16, mmInfo, quantInfo).GetSize();
+}
