+static ge::graphStatus MatmulAllreduceAddRmsnorm910cTilingFuncImpl(gert::TilingContext *context)
+{
+    const char *nodeName = context->GetNodeName();
+    MatmulAllreduceAddRmsnorm910cTilingData *tilingData = context->GetTilingData<MatmulAllreduceAddRmsnorm910cTilingData>();
+    OPS_ERR_IF(tilingData == nullptr, OPS_LOG_E(nodeName, "tilingData is nullptr."), return ge::GRAPH_FAILED);
+
+    OPS_ERR_IF(GetAttrAndSetTilingData(context, nodeName, *tilingData) != ge::GRAPH_SUCCESS,
+        OPS_LOG_E(nodeName, "Get attr and set tiling data failed."),
+        return ge::GRAPH_FAILED);
+    OPS_ERR_IF(SetWorkSpace(context, nodeName) != ge::GRAPH_SUCCESS,
+        OPS_LOG_E(nodeName, "Tiling set workspace failed."),
+        return ge::GRAPH_FAILED);
+    auto attrs = context->GetAttrs();
+    OPS_ERR_IF(attrs == nullptr, OPS_LOG_E(nodeName, "attrs is nullptr."), return ge::GRAPH_FAILED);
+    auto groupTpPtr = attrs->GetAttrPointer<char>(ATTR_TP_INDEX);
+    OPS_ERR_IF(groupTpPtr == nullptr || groupTpPtr[0] == '\0',
+        OPS_LOG_E(nodeName, "group_tp is invalid."), return ge::GRAPH_FAILED);
+    SetHcommCfg(context, tilingData, std::string(groupTpPtr));
+
+    fe::PlatFormInfos* platformInfoPtr = context->GetPlatformInfo();
+    OPS_LOG_E_IF_NULL(context, platformInfoPtr, return ge::GRAPH_FAILED);
+    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
+    uint32_t aicNum_ = ascendcPlatform.GetCoreNumAic();
+    context->SetBlockDim(aicNum_);
+    return ge::GRAPH_SUCCESS;
+}
+
+static ge::graphStatus MatmulAllreduceAddRmsnorm910cTilingFunc(gert::TilingContext *context)
+{
+    ge::graphStatus ret = MatmulAllreduceAddRmsnorm910cTilingFuncImpl(context);
+    return ret;
