+        GlobalTensor<int32_t> stateControl;
+        stateControl.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(
+            localStatusBase + dataBank_ * STATUS_BANK_STRIDE + STATUS_CONTROL_OFFSET));
