+        LocalTensor<float> statusSum = statusSumBuffer_.Get<float>();
+        GlobalTensor<float> localStatus;
+        localStatus.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(
+            GetStatusAddress(rank_) + coreIndex_ * UB_ALIGN_BYTES));
