+    double c2 = sqrt(c1);
+    double c3 = sqrt(1.0 * m * n) / k;
+    double c4 = c3 * c3;
+    double c5 = matmulPredict;
+    double c6 = commPredict;
+    double c7 = 1.0 * n / m;
+    double c8 = 1.0 * m * n / sqrt(k);
+    double c9 = 1.0 * m * n * sqrt(k);
+    double c10 = sqrt(1.0 * m * n) * k;
