+static ge::graphStatus MatmulAllreduceAddRmsnorm910cTilingFunc(gert::TilingContext *context)
+{
+    ge::graphStatus ret = MatmulAllreduceAddRmsnorm910cTilingFuncImpl(context);
+    return ret;
+}
